import{_ as e,o as a,c as l,ae as r}from"./chunks/framework.Czhw_PXq.js";const t="/project-microservice.png",o="/project-microservice-arch.png",_=JSON.parse('{"title":"微服务电商平台","description":"","frontmatter":{"layout":"doc","title":"微服务电商平台"},"headers":[],"relativePath":"projects/microservice.md","filePath":"projects/microservice.md"}'),s={name:"projects/microservice.md"};function n(c,i,d,h,u,m){return a(),l("div",null,[...i[0]||(i[0]=[r('<h1 id="微服务电商平台" tabindex="-1">微服务电商平台 <a class="header-anchor" href="#微服务电商平台" aria-label="Permalink to &quot;微服务电商平台&quot;">​</a></h1><h2 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to &quot;项目介绍&quot;">​</a></h2><p>基于 Spring Cloud 开发的高并发、高可用电商平台，集成 AI 推荐、智能客服、数据分析等功能，支持日均 10 万订单量，可扩展至百万级流量，适用于 B2C 电商、新零售等业务场景。</p><div style="text-align:center;margin:2rem 0;"><img src="'+t+'" alt="微服务电商平台界面" style="width:80%;border-radius:14px;box-shadow:0 4px 16px rgba(0,0,0,0.1);"></div><h2 id="核心技术栈" tabindex="-1">核心技术栈 <a class="header-anchor" href="#核心技术栈" aria-label="Permalink to &quot;核心技术栈&quot;">​</a></h2><ul><li>后端框架：Spring Cloud + Spring Boot</li><li>服务治理：Nacos + Sentinel + OpenFeign</li><li>数据库：MySQL + Redis + Elasticsearch</li><li>消息队列：RabbitMQ</li><li>部署：Docker + Kubernetes</li><li>AI 功能：LangChain + 通义千问（推荐/客服）</li></ul><h2 id="核心功能模块" tabindex="-1">核心功能模块 <a class="header-anchor" href="#核心功能模块" aria-label="Permalink to &quot;核心功能模块&quot;">​</a></h2><ol><li>用户服务：注册登录、权限管理、个人中心</li><li>商品服务：商品管理、分类、搜索、库存</li><li>订单服务：下单、支付、物流、售后</li><li>支付服务：多支付渠道集成、对账</li><li>AI 推荐：基于用户行为的个性化商品推荐</li><li>智能客服：7x24小时自动回复、问题转接</li><li>数据分析：销售报表、用户画像、流量分析</li></ol><h2 id="项目架构" tabindex="-1">项目架构 <a class="header-anchor" href="#项目架构" aria-label="Permalink to &quot;项目架构&quot;">​</a></h2><div style="text-align:center;margin:2rem 0;"><img src="'+o+'" alt="微服务电商平台架构" style="width:90%;border-radius:14px;"></div><h2 id="技术亮点" tabindex="-1">技术亮点 <a class="header-anchor" href="#技术亮点" aria-label="Permalink to &quot;技术亮点&quot;">​</a></h2><ul><li>高并发设计：缓存预热、限流熔断、分布式锁</li><li>高可用：服务集群、故障转移、数据备份</li><li>可扩展：微服务拆分，支持按需扩容</li><li>AI 赋能：提升用户体验和运营效率</li><li>全链路监控：SkyWalking 链路追踪、日志分析</li></ul><h2 id="部署环境" tabindex="-1">部署环境 <a class="header-anchor" href="#部署环境" aria-label="Permalink to &quot;部署环境&quot;">​</a></h2><ul><li>开发环境：Docker Compose</li><li>测试环境：Kubernetes 集群</li><li>生产环境：阿里云 ECS + 容器服务</li></ul>',14)])])}const b=e(s,[["render",n]]);export{_ as __pageData,b as default};
